import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String rateText = sc.nextLine().trim();
        List<String> amounts = new ArrayList<>();
        while (sc.hasNextLine()) {
            String s = sc.nextLine().trim();
            if (!s.isEmpty()) {
                amounts.add(s);
            }
        }
        double rate = Double.parseDouble(rateText); // TODO: BigDecimal for exact, rule A, rule B, A - B
        double sum = 0;
        for (String a : amounts) {
            sum += Double.parseDouble(a) * rate;
        }
        System.out.println("exact VAT: " + sum);
        System.out.println("rule A (round each line): " + Math.round(sum));
        System.out.println("rule B (round the total): " + Math.round(sum));
        System.out.println("A - B: 0");
        System.out.println("double: " + sum);
    }
}

